item.aggregated_output:
 1	module TopModule(
 2		input clk,
 3		input rst_n,
 4		input set,
 5		input [3:0] set_num,
 6		output reg [3:0]number,
 7		output reg zero
 8		);
 9		reg [3:0]num;
10		
11		always @(posedge clk or negedge rst_n)
12			if (!rst_n)
13				begin 
14					num <= 4'b0;
15					number <= 4'b0;
16					zero <= 1'b1;
17				end
18			else if(set)
19				begin
20					num <= set_num;
21					number <= set_num;
22					zero <= (set_num == 4'd0);
23				end
24			else 
25				begin
26					num <= num + 4'd1;
27					number <= num + 4'd1;
28					zero <= ((num + 4'd1) == 4'd0);
29				end
30	
31	endmodule
